export type IconPrimitive = string | number | boolean;
export type IconAttributeValue = IconPrimitive | null | undefined;
/**
 * Any CSS color value understood by the consumer's browser/runtime.
 * Moexi treats colors as opaque CSS strings so modern syntax such as
 * oklch(), lab(), lch(), color(), color-mix(), and var() passes through.
 */
export type CssColorValue = string;
export type IconAttributes = Readonly<Record<string, IconAttributeValue>>;
/** A semantic paint slot such as primary, secondary, accent, or outline. */
export type IconPaintToken = string;
/** Default or resolved values for semantic paint slots. */
export type IconPalette = Readonly<Record<IconPaintToken, CssColorValue>>;
/** Consumer overrides for semantic paint slots. Partial overrides are allowed. */
export type IconColorOverrides = Readonly<Record<IconPaintToken, CssColorValue>>;
/**
 * Maps an SVG paint channel to a semantic token. Tokens are resolved by the
 * Moexi resolver before framework/DOM/SVG renderers see the geometry.
 */
export interface IconNodePaint {
    readonly fill?: IconPaintToken;
    readonly stroke?: IconPaintToken;
    readonly color?: IconPaintToken;
}
/** Geometry-first SVG tags supported by the Moexi icon specification. */
export type IconNodeTag = 'path' | 'line' | 'circle' | 'rect' | 'ellipse' | 'polyline' | 'polygon' | 'g';
export interface IconNode {
    readonly tag: IconNodeTag;
    readonly attrs?: IconAttributes;
    readonly children?: readonly IconNode[];
    /** Optional semantic layer used for scoped customization and tooling. */
    readonly layer?: string;
    /** Optional semantic role describing what the node represents. */
    readonly role?: string;
    /** Optional semantic paint channels resolved against the effective palette. */
    readonly paint?: IconNodePaint;
}
/** Structured deprecation metadata. Renderers should never warn implicitly. */
export interface IconDeprecation {
    readonly since: string;
    readonly replacement?: string;
    readonly message?: string;
}
export interface IconMetadata {
    readonly category?: string;
    readonly tags?: readonly string[];
    readonly aliases?: readonly string[];
    readonly added?: string;
    readonly deprecated?: IconDeprecation;
}
export interface IconVariantDefinition {
    /** Root SVG attributes merged over the base icon attributes. */
    readonly attrs?: IconAttributes;
    /** Optional complete geometry replacement for this variant. */
    readonly nodes?: readonly IconNode[];
    /** Variant-specific semantic paint defaults merged over the base palette. */
    readonly palette?: IconPalette;
}
export interface IconDefinition {
    readonly name: string;
    readonly viewBox?: string;
    readonly attrs?: IconAttributes;
    readonly nodes: readonly IconNode[];
    /** Base semantic paint defaults shared by all variants. */
    readonly palette?: IconPalette;
    readonly defaultVariant?: string;
    readonly variants?: Readonly<Record<string, IconVariantDefinition>>;
    readonly metadata?: IconMetadata;
}
export interface IconPackMetadata {
    readonly description?: string;
    readonly license?: string;
    readonly homepage?: string;
}
/**
 * Portable collection contract for official and third-party Moexi packs.
 * A namespace keeps multiple packs with overlapping icon names deterministic.
 */
export interface IconPackDefinition {
    readonly name: string;
    readonly version: string;
    readonly specVersion: string;
    readonly namespace?: string;
    readonly icons: readonly IconDefinition[];
    readonly metadata?: IconPackMetadata;
}
export type IconVariantName<T extends IconDefinition> = T['variants'] extends Readonly<Record<infer K, IconVariantDefinition>> ? K & string : string;
export interface IconLayerOverride {
    /** Hide the layer and its subtree from the resolved icon. */
    readonly hidden?: boolean;
    /** Attributes applied after semantic paints for nodes in this layer. */
    readonly attrs?: IconAttributes;
    /** Layer-scoped semantic color overrides. */
    readonly colors?: IconColorOverrides;
}
export type IconLayerOverrides = Readonly<Record<string, IconLayerOverride>>;
export interface IconRenderOptions<Variant extends string = string> {
    readonly size?: string | number;
    readonly width?: string | number;
    readonly height?: string | number;
    readonly variant?: Variant;
    readonly strokeWidth?: string | number;
    /** Root CSS color used by currentColor-based geometry. */
    readonly color?: CssColorValue;
    /** Partial semantic paint overrides, e.g. { accent: 'oklch(...)' }. */
    readonly colors?: IconColorOverrides;
    /** Optional semantic layer customization. */
    readonly layers?: IconLayerOverrides;
    readonly className?: string;
    readonly title?: string;
    readonly ariaLabel?: string;
    /** Explicit accessibility mode. Defaults to decorative when no accessible name is supplied. */
    readonly decorative?: boolean;
    /** Additional root SVG attributes. These are applied last. */
    readonly attrs?: IconAttributes;
}
export interface ResolvedIconNode {
    readonly tag: IconNodeTag;
    readonly attrs?: Readonly<Record<string, IconPrimitive>>;
    readonly children?: readonly ResolvedIconNode[];
    readonly layer?: string;
    readonly role?: string;
}
export interface ResolvedIcon {
    readonly name: string;
    readonly viewBox: string;
    readonly attrs: Readonly<Record<string, IconPrimitive>>;
    readonly nodes: readonly ResolvedIconNode[];
    readonly variant?: string;
    readonly colors: IconPalette;
    readonly title?: string;
}
/** Discoverable features derived from an icon definition, never hard-coded per renderer. */
export interface IconCapabilities {
    readonly variants: readonly string[];
    readonly defaultVariant?: string;
    readonly paintTokens: readonly string[];
    readonly layers: readonly string[];
    readonly roles: readonly string[];
    readonly colorVariants: readonly string[];
    readonly supportsSemanticPaints: boolean;
    readonly supportsPaletteOverrides: boolean;
    readonly supportsLayerOverrides: boolean;
    readonly multicolorCapable: boolean;
}
export interface IconRegistryEntry {
    readonly key: string;
    readonly canonicalName: string;
    readonly definition: IconDefinition;
    readonly packName?: string;
    readonly namespace?: string;
}
export interface IconRegistryResolution extends IconRegistryEntry {
    readonly requestedName: string;
    readonly viaAlias: boolean;
    readonly deprecation?: IconDeprecation;
    readonly replacementKey?: string;
}
export interface IconRegistryOptions {
    readonly icons?: readonly IconDefinition[];
    readonly packs?: readonly IconPackDefinition[];
}
